; Split a DMA task if this art copy straddles a 128 KiB source bank.
soloTailsDplcEntry macro count,first
	if (((ArtUnc_SoloTails+(first)*32)&$1FFFF)+(count)*32)>$20000
		dplcEntry ($20000-((ArtUnc_SoloTails+(first)*32)&$1FFFF))/32, first
